package com.salespunch360.mobile.ui.account.purchase
import androidx.compose.foundation.clickable;import androidx.compose.foundation.layout.*;import androidx.compose.foundation.lazy.LazyColumn;import androidx.compose.foundation.lazy.LazyRow;import androidx.compose.foundation.lazy.items;import androidx.compose.material.icons.Icons;import androidx.compose.material.icons.filled.Add;import androidx.compose.material.icons.filled.Refresh;import androidx.compose.material3.*;import androidx.compose.runtime.*;import androidx.compose.ui.Modifier;import androidx.compose.ui.text.font.FontWeight;import androidx.compose.ui.unit.dp;import androidx.lifecycle.compose.collectAsStateWithLifecycle;import androidx.lifecycle.viewmodel.compose.viewModel;import com.salespunch360.mobile.AccountPurchaseViewModel
@Composable fun PurchaseScreen(initialType:String?,padding:PaddingValues,vm:AccountPurchaseViewModel=viewModel()){val s=vm.state.collectAsStateWithLifecycle().value;LaunchedEffect(initialType){if(initialType!=null)vm.filter(initialType)};Column(Modifier.fillMaxSize().padding(padding).padding(horizontal=16.dp)){Row{OutlinedTextField(s.query,vm::search,label={Text("Search number or vendor")},modifier=Modifier.weight(1f));IconButton(vm::refresh){Icon(Icons.Default.Refresh,"Refresh")};FilledIconButton({vm.create(initialType?:s.types.firstOrNull().orEmpty())},enabled=s.types.isNotEmpty()){Icon(Icons.Default.Add,"New purchase")}};LazyRow(horizontalArrangement=Arrangement.spacedBy(6.dp)){item{FilterChip(s.type==null,{vm.filter(null)},{Text("All")})};items(s.types){t->FilterChip(s.type==t,{vm.filter(t)},{Text(t.replace('_',' '))})}};if(s.loading)LinearProgressIndicator(Modifier.fillMaxWidth());s.error?.let{Card(colors=CardDefaults.cardColors(containerColor=MaterialTheme.colorScheme.errorContainer)){Row(Modifier.padding(12.dp)){Text(it,Modifier.weight(1f));TextButton(vm::refresh){Text("Retry")}}}};LazyColumn(Modifier.fillMaxSize()){items(s.rows,key={it.id}){x->ListItem(headlineContent={Text(x.number,fontWeight=FontWeight.Bold)},supportingContent={Text("${x.party} · ${x.date} · ${x.type.replace('_',' ')}")},trailingContent={Column{Text("₹${x.total}");Text(x.status)}},modifier=Modifier.clickable{vm.open(x.id)})}}};s.draft?.let{PurchaseEditor(it,s,vm)};s.detail?.let{PurchaseDetail(it,s.saving,vm::close,vm::askPost)};s.posting?.let{AlertDialog(onDismissRequest=vm::cancelPost,title={Text("Post purchase document?")},text={Text("The server will validate the financial year, period lock, tax, stock, and ledger posting.")},confirmButton={Button(vm::post){Text("Post")}},dismissButton={TextButton(vm::cancelPost){Text("Cancel")}})}}}
